        "Dein Körper-Fortschritt": [.en: "Your body progress", .fr: "Ta progression physique", .es: "Tu progreso físico", .it: "I tuoi progressi fisici", .hi: "आपकी शारीरिक प्रगति"],
        "Mache regelmäßig Fotos und erhalte KI-Feedback zu deinem Fortschritt.": [.en: "Take regular photos and get AI feedback on your progress.", .fr: "Prends des photos régulièrement et reçois un retour IA sur ta progression.", .es: "Toma fotos regularmente y recibe comentarios de IA sobre tu progreso.", .it: "Scatta foto regolarmente e ricevi feedback IA sui tuoi progressi.", .hi: "नियमित रूप से फ़ोटो लें और अपनी प्रगति पर एआई फ़ीडबैक प्राप्त करें।"],
        "Tippe auf + um dein erstes Transformationsfoto hinzuzufügen.": [.en: "Tap + to add your first transformation photo.", .fr: "Touche + pour ajouter ta première photo de transformation.", .es: "Toca + para añadir tu primera foto de transformación.", .it: "Tocca + per aggiungere la tua prima foto di trasformazione.", .hi: "अपनी पहली परिवर्तन फ़ोटो जोड़ने के लिए + पर टैप करें।"],
        "Erstes Foto hinzufügen": [.en: "Add first photo", .fr: "Ajouter la première photo", .es: "Añadir primera foto", .it: "Aggiungi prima foto", .hi: "पहली फ़ोटो जोड़ें"],
        "Vergleich: Anfang vs. Jetzt": [.en: "Comparison: Start vs. Now", .fr: "Comparaison : Début vs. Maintenant", .es: "Comparación: Inicio vs. Ahora", .it: "Confronto: Inizio vs. Ora", .hi: "तुलना: शुरुआत बनाम अभी"],
        "Anfang": [.en: "Start", .fr: "Début", .es: "Inicio", .it: "Inizio", .hi: "शुरुआत"],
        "Aktuell": [.en: "Current", .fr: "Actuel", .es: "Actual", .it: "Attuale", .hi: "वर्तमान"],
        "Analyse läuft…": [.en: "Analyzing…", .fr: "Analyse en cours…", .es: "Analizando…", .it: "Analisi in corso…", .hi: "विश्लेषण हो रहा है…"],
        "KI-Feedback erhalten": [.en: "Get AI feedback", .fr: "Obtenir un retour IA", .es: "Obtener comentarios de IA", .it: "Ricevi feedback IA", .hi: "एआई फ़ीडबैक प्राप्त करें"],
        "KI-Feedback": [.en: "AI feedback", .fr: "Retour IA", .es: "Comentarios de IA", .it: "Feedback IA", .hi: "एआई फ़ीडबैक"],
        "Verlauf": [.en: "History", .fr: "Historique", .es: "Historial", .it: "Cronologia", .hi: "इतिहास"],
        "Tolle Arbeit, dass du deinen Fortschritt dokumentierst! Bleib konsequent und mache alle 2 Wochen ein neues Foto, um deinen Fortschritt sichtbar zu machen.": [.en: "Great job documenting your progress! Stay consistent and take a new photo every 2 weeks to make your progress visible.", .fr: "Excellent travail pour documenter tes progrès ! Reste cohérent et prends une nouvelle photo toutes les 2 semaines pour rendre tes progrès visibles.", .es: "¡Buen trabajo documentando tu progreso! Mantente constante y toma una nueva foto cada 2 semanas para hacer visible tu progreso.", .it: "Ottimo lavoro nel documentare i tuoi progressi! Rimani costante e scatta una nuova foto ogni 2 settimane per rendere visibili i tuoi progressi.", .hi: "अपनी प्रगति को दर्ज करने के लिए बढ़िया काम! निरंतर बने रहें और अपनी प्रगति को दृश्यमान बनाने के लिए हर 2 सप्ताह में एक नई फ़ोटो लें।"],
        "Foto hinzufügen": [.en: "Add photo", .fr: "Ajouter une photo", .es: "Añadir foto", .it: "Aggiungi foto", .hi: "फ़ोटो जोड़ें"],
        "Foto auswählen": [.en: "Select photo", .fr: "Sélectionner une photo", .es: "Seleccionar foto", .it: "Seleziona foto", .hi: "फ़ोटो चुनें"],
        "Kamera": [.en: "Camera", .fr: "Appareil photo", .es: "Cámara", .it: "Fotocamera", .hi: "कैमरा"],
        "Galerie": [.en: "Gallery", .fr: "Galerie", .es: "Galería", .it: "Galleria", .hi: "गैलरी"],
        "Notiz (optional)": [.en: "Note (optional)", .fr: "Note (facultatif)", .es: "Nota (opcional)", .it: "Nota (opzionale)", .hi: "नोट (वैकल्पिक)"],
        "z.B. Nach 4 Wochen Training": [.en: "e.g. After 4 weeks of training", .fr: "p. ex. Après 4 semaines d'entraînement", .es: "p. ej. Después de 4 semanas de entrenamiento", .it: "es. Dopo 4 settimane di allenamento", .hi: "जैसे, 4 सप्ताह के प्रशिक्षण के बाद"],

        // ===== PROFILE: NUTRITION GOALS / APPEARANCE =====
        "Ernährungsziele": [.en: "Nutrition Goals", .fr: "Objectifs nutritionnels", .es: "Objetivos nutricionales", .it: "Obiettivi nutrizionali", .hi: "पोषण लक्ष्य"],
        "Passe deine täglichen Makroziele an.": [.en: "Adjust your daily macro goals.", .fr: "Ajuste tes objectifs de macros quotidiens.", .es: "Ajusta tus objetivos diarios de macros.", .it: "Regola i tuoi obiettivi giornalieri di macro.", .hi: "अपने दैनिक मैक्रो लक्ष्यों को समायोजित करें।"],
        "Gespeichert": [.en: "Saved", .fr: "Enregistré", .es: "Guardado", .it: "Salvato", .hi: "सहेजा गया"],
        "Ziele speichern": [.en: "Save goals", .fr: "Enregistrer les objectifs", .es: "Guardar objetivos", .it: "Salva obiettivi", .hi: "लक्ष्य सहेजें"],
        "Wähle, wie Frigy aussehen soll. Die Änderung wird sofort übernommen.": [.en: "Choose how Frigy should look. The change applies immediately.", .fr: "Choisis l'apparence de Frigy. Le changement s'applique immédiatement.", .es: "Elige el aspecto de Frigy. El cambio se aplica de inmediato.", .it: "Scegli l'aspetto di Frigy. La modifica si applica subito.", .hi: "चुनें कि Frigy कैसा दिखे। परिवर्तन तुरंत लागू होता है।"],

        // ===== PROFILE: SUBSCRIPTION / PRIVACY / HELP =====
        "Unbegrenzte KI-Mahlzeitenpläne": [.en: "Unlimited AI meal plans", .fr: "Plans de repas IA illimités", .es: "Planes de comidas con IA ilimitados", .it: "Piani alimentari IA illimitati", .hi: "असीमित एआई भोजन योजनाएं"],
        "KI-Coach ohne Limits": [.en: "AI coach without limits", .fr: "Coach IA sans limites", .es: "Entrenador de IA sin límites", .it: "Coach IA senza limiti", .hi: "बिना सीमा के एआई कोच"],
        "Barcode & Foto-Scan": [.en: "Barcode & photo scan", .fr: "Scan de code-barres et photo", .es: "Escaneo de código de barras y foto", .it: "Scansione codice a barre e foto", .hi: "बारकोड और फ़ोटो स्कैन"],
        "Erweiterte Fortschrittsdiagramme": [.en: "Advanced progress charts", .fr: "Graphiques de progression avancés", .es: "Gráficos de progreso avanzados", .it: "Grafici di progresso avanzati", .hi: "उन्नत प्रगति चार्ट"],
        "Jetzt upgraden – %1 / %2": [.en: "Upgrade now – %1 / %2", .fr: "Mettre à niveau – %1 / %2", .es: "Actualizar ahora – %1 / %2", .it: "Aggiorna ora – %1 / %2", .hi: "अभी अपग्रेड करें – %1 / %2"],
        "Jetzt upgraden": [.en: "Upgrade now", .fr: "Mettre à niveau", .es: "Actualizar ahora", .it: "Aggiorna ora", .hi: "अभी अपग्रेड करें"],
        "Gutscheincode einlösen": [.en: "Redeem voucher code", .fr: "Utiliser un code promo", .es: "Canjear código de promoción", .it: "Riscatta codice promozionale", .hi: "वाउचर कोड रिडीम करें"],
        "Datenerhebung": [.en: "Data Collection", .fr: "Collecte de données", .es: "Recopilación de datos", .it: "Raccolta dati", .hi: "डेटा संग्रह"],
        "Frigy speichert nur die Daten, die du aktiv eingibst: Mahlzeiten, Gewicht und deine Profileinstellungen. Alle Daten werden verschlüsselt und sicher in unserer Datenbank gespeichert.": [.en: "Frigy only stores the data you actively enter: meals, weight, and your profile settings. All data is encrypted and stored securely in our database.", .fr: "Frigy ne stocke que les données que tu saisis activement : repas, poids et paramètres de profil. Toutes les données sont chiffrées et stockées en toute sécurité dans notre base de données.", .es: "Frigy solo almacena los datos que ingresas activamente: comidas, peso y la configuración de tu perfil. Todos los datos se cifran y almacenan de forma segura en nuestra base de datos.", .it: "Frigy memorizza solo i dati che inserisci attivamente: pasti, peso e le impostazioni del tuo profilo. Tutti i dati sono crittografati e archiviati in modo sicuro nel nostro database.", .hi: "Frigy केवल वह डेटा संग्रहीत करता है जो आप सक्रिय रूप से दर्ज करते हैं: भोजन, वजन और आपकी प्रोफ़ाइल सेटिंग्स। सभी डेटा एन्क्रिप्ट किया जाता है और हमारे डेटाबेस में सुरक्षित रूप से संग्रहीत किया जाता है।"],
        "Datenweitergabe": [.en: "Data Sharing", .fr: "Partage des données", .es: "Compartición de datos", .it: "Condivisione dati", .hi: "डेटा साझाकरण"],
        "Deine persönlichen Daten werden niemals an Dritte verkauft oder ohne deine ausdrückliche Zustimmung weitergegeben.": [.en: "Your personal data is never sold to third parties or shared without your explicit consent.", .fr: "Tes données personnelles ne sont jamais vendues à des tiers ni partagées sans ton consentement explicite.", .es: "Tus datos personales nunca se venden a terceros ni se comparten sin tu consentimiento explícito.", .it: "I tuoi dati personali non vengono mai venduti a terzi né condivisi senza il tuo esplicito consenso.", .hi: "आपका व्यक्तिगत डेटा कभी भी तीसरे पक्ष को नहीं बेचा जाता या आपकी स्पष्ट सहमति के बिना साझा नहीं किया जाता।"],
        "Datenlöschung": [.en: "Data Deletion", .fr: "Suppression des données", .es: "Eliminación de datos", .it: "Cancellazione dati", .hi: "डेटा हटाना"],
        "Du kannst jederzeit die vollständige Löschung deiner Daten beantragen. Schreib uns einfach an support@frigy.app.": [.en: "You can request the complete deletion of your data at any time. Just email us at support@frigy.app.", .fr: "Tu peux demander la suppression complète de tes données à tout moment. Écris-nous simplement à support@frigy.app.", .es: "Puedes solicitar la eliminación completa de tus datos en cualquier momento. Solo escríbenos a support@frigy.app.", .it: "Puoi richiedere la cancellazione completa dei tuoi dati in qualsiasi momento. Scrivici semplicemente a support@frigy.app.", .hi: "आप किसी भी समय अपने डेटा को पूरी तरह से हटाने का अनुरोध कर सकते हैं। बस हमें support@frigy.app पर लिखें।"],
        "KI-Verarbeitung": [.en: "AI Processing", .fr: "Traitement IA", .es: "Procesamiento de IA", .it: "Elaborazione IA", .hi: "एआई प्रसंस्करण"],
        "Anfragen an den KI-Coach werden verschlüsselt übertragen. Deine Daten werden nicht zur Verbesserung von KI-Modellen verwendet.": [.en: "Requests to the AI coach are transmitted encrypted. Your data is not used to improve AI models.", .fr: "Les demandes adressées au coach IA sont transmises de manière chiffrée. Tes données ne sont pas utilisées pour améliorer les modèles d'IA.", .es: "Las solicitudes al entrenador de IA se transmiten cifradas. Tus datos no se utilizan para mejorar los modelos de IA.", .it: "Le richieste al coach IA vengono trasmesse in modo crittografato. I tuoi dati non vengono utilizzati per migliorare i modelli IA.", .hi: "एआई कोच को अनुरोध एन्क्रिप्ट किए गए भेजे जाते हैं। आपके डेटा का उपयोग एआई मॉडल को बेहतर बनाने के लिए नहीं किया जाता।"],
        "Datensicherheit": [.en: "Data Security", .fr: "Sécurité des données", .es: "Seguridad de datos", .it: "Sicurezza dei dati", .hi: "डेटा सुरक्षा"],
        "Wir verwenden branchenübliche Sicherheitsmaßnahmen (TLS, AES-256) um deine Daten zu schützen. Passwörter werden niemals im Klartext gespeichert.": [.en: "We use industry-standard security measures (TLS, AES-256) to protect your data. Passwords are never stored in plain text.", .fr: "Nous utilisons des mesures de sécurité standard du secteur (TLS, AES-256) pour protéger tes données. Les mots de passe ne sont jamais stockés en clair.", .es: "Utilizamos medidas de seguridad estándar del sector (TLS, AES-256) para proteger tus datos. Las contraseñas nunca se almacenan en texto plano.", .it: "Utilizziamo misure di sicurezza standard del settore (TLS, AES-256) per proteggere i tuoi dati. Le password non vengono mai memorizzate in chiaro.", .hi: "हम आपके डेटा की सुरक्षा के लिए उद्योग-मानक सुरक्षा उपाय (TLS, AES-256) का उपयोग करते हैं। पासवर्ड कभी भी सादे पाठ में संग्रहीत नहीं किए जाते।"],
        "Deine Daten gehören dir": [.en: "Your data belongs to you", .fr: "Tes données t'appartiennent", .es: "Tus datos te pertenecen", .it: "I tuoi dati appartengono a te", .hi: "आपका डेटा आपका है"],
        "Wir nehmen Datenschutz ernst.": [.en: "We take privacy seriously.", .fr: "Nous prenons la confidentialité au sérieux.", .es: "Nos tomamos en serio la privacidad.", .it: "Prendiamo sul serio la privacy.", .hi: "हम गोपनीयता को गंभीरता से लेते हैं।"],
        "Letzte Aktualisierung: Januar 2025\nFragen? support@frigy.app": [.en: "Last updated: January 2025\nQuestions? support@frigy.app", .fr: "Dernière mise à jour : janvier 2025\nQuestions ? support@frigy.app", .es: "Última actualización: enero de 2025\n¿Preguntas? support@frigy.app", .it: "Ultimo aggiornamento: gennaio 2025\nDomande? support@frigy.app", .hi: "अंतिम अपडेट: जनवरी 2025\nप्रश्न? support@frigy.app"],
        "HÄUFIGE FRAGEN": [.en: "FREQUENTLY ASKED QUESTIONS", .fr: "QUESTIONS FRÉQUENTES", .es: "PREGUNTAS FRECUENTES", .it: "DOMANDE FREQUENTI", .hi: "अक्सर पूछे जाने वाले प्रश्न"],
        "Wie tracke ich Mahlzeiten?": [.en: "How do I track meals?", .fr: "Comment suivre mes repas ?", .es: "¿Cómo registro mis comidas?", .it: "Come traccio i pasti?", .hi: "मैं भोजन कैसे ट्रैक करूं?"],
        "Tippe im Home-Tab auf + oder wähle eine Mahlzeitkategorie, um Lebensmittel zu suchen und zu tracken.": [.en: "Tap + in the Home tab or choose a meal category to search for and track food.", .fr: "Touche + dans l'onglet Accueil ou choisis une catégorie de repas pour rechercher et suivre des aliments.", .es: "Toca + en la pestaña de Inicio o elige una categoría de comida para buscar y registrar alimentos.", .it: "Tocca + nella scheda Home o scegli una categoria di pasto per cercare e tracciare gli alimenti.", .hi: "होम टैब में + पर टैप करें या भोजन खोजने और ट्रैक करने के लिए एक भोजन श्रेणी चुनें।"],
        "Wie ändere ich meine Kalorienziele?": [.en: "How do I change my calorie goals?", .fr: "Comment modifier mes objectifs caloriques ?", .es: "¿Cómo cambio mis objetivos de calorías?", .it: "Come modifico i miei obiettivi calorici?", .hi: "मैं अपने कैलोरी लक्ष्य कैसे बदलूं?"],
        "Gehe zu Profil → Ernährungsziele und passe die Werte mit den Schiebereglern an.": [.en: "Go to Profile → Nutrition Goals and adjust the values with the sliders.", .fr: "Va dans Profil → Objectifs nutritionnels et ajuste les valeurs avec les curseurs.", .es: "Ve a Perfil → Objetivos nutricionales y ajusta los valores con los controles deslizantes.", .it: "Vai su Profilo → Obiettivi nutrizionali e regola i valori con i cursori.", .hi: "प्रोफ़ाइल → पोषण लक्ष्य पर जाएं और स्लाइडर से मान समायोजित करें।"],
        "Kann ich Gewicht tracken?": [.en: "Can I track weight?", .fr: "Puis-je suivre mon poids ?", .es: "¿Puedo registrar mi peso?", .it: "Posso tracciare il peso?", .hi: "क्या मैं वजन ट्रैक कर सकता हूं?"],
        "Ja! Im Home-Tab auf 'Gewicht' tippen, dann auf + um ein neues Gewicht einzutragen.": [.en: "Yes! Tap 'Weight' in the Home tab, then + to log a new weight.", .fr: "Oui ! Touche « Poids » dans l'onglet Accueil, puis + pour enregistrer un nouveau poids.", .es: "¡Sí! Toca 'Peso' en la pestaña de Inicio, luego + para registrar un nuevo peso.", .it: "Sì! Tocca 'Peso' nella scheda Home, poi + per registrare un nuovo peso.", .hi: "हां! होम टैब में 'वजन' पर टैप करें, फिर नया वजन दर्ज करने के लिए + पर टैप करें।"],

        // ===== PROFILE: WEIGHT PROGRESS =====
        "Gewichtsverlauf": [.en: "Weight History", .fr: "Historique du poids", .es: "Historial de peso", .it: "Storico del peso", .hi: "वजन इतिहास"],
        "Noch keine Gewichtseinträge": [.en: "No weight entries yet", .fr: "Aucune entrée de poids pour l'instant", .es: "Aún no hay registros de peso", .it: "Ancora nessuna voce di peso", .hi: "अभी तक कोई वजन प्रविष्टि नहीं"],
        "Tippe auf +, um dein erstes Gewicht einzutragen.": [.en: "Tap + to log your first weight.", .fr: "Touche + pour enregistrer ton premier poids.", .es: "Toca + para registrar tu primer peso.", .it: "Tocca + per registrare il tuo primo peso.", .hi: "अपना पहला वजन दर्ज करने के लिए + पर टैप करें।"],
        "Verlust": [.en: "Loss", .fr: "Perte", .es: "Pérdida", .it: "Perdita", .hi: "हानि"],
        "Zuwachs": [.en: "Gain", .fr: "Gain", .es: "Ganancia", .it: "Aumento", .hi: "वृद्धि"],
        "Gewicht eintragen": [.en: "Log weight", .fr: "Enregistrer le poids", .es: "Registrar peso", .it: "Registra peso", .hi: "वजन दर्ज करें"],
        "z.B. 74,5": [.en: "e.g. 74.5", .fr: "p. ex. 74,5", .es: "p. ej. 74,5", .it: "es. 74,5", .hi: "जैसे, 74.5"],
